<fieldset class="card p-4 my-4"><legend class="h5">Reporte de robo</legend><label class="form-check"><input type="checkbox" class="form-check-input" name="has_theft_report" value="1" @checked(old('has_theft_report', (bool)$vehiculo->theftReport))> Incluir reporte</label><label class="form-label mt-3" for="theft_report_date">Fecha del reporte</label><input class="form-control" type="date" id="theft_report_date" name="theft_report_date" value="{{ old('theft_report_date', $vehiculo->theftReport?->report_date?->format('Y-m-d')) }}"><label class="form-label mt-3" for="theft_description">Descripción</label><textarea id="theft_description" class="form-control" name="theft_description">{{ old('theft_description', $vehiculo->theftReport?->description) }}</textarea>@if(auth()->user()->role?->name === 'admin')<label class="form-label mt-3" for="theft_report_status">Revisión administrativa</label><select class="form-select" id="theft_report_status" name="theft_report_status">@foreach(['pendiente_validacion','validado','rechazado','resuelto'] as $status)<option value="{{ $status }}" @selected(old('theft_report_status', $vehiculo->theftReport?->status) === $status)>{{ ucfirst(str_replace('_',' ',$status)) }}</option>@endforeach</select>@else<p class="text-secondary mt-3">Los reportes nuevos o modificados requieren validación posterior. Retirar un reporte conserva su historial en la bitácora.</p>@endif</fieldset>